            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            pts = set(cells)
            perimeter = all((y, x) in pts for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                            if y in (r0, r1) or x in (c0, c1))
            hollow = perimeter and len(cells) < (r1 - r0 + 1) * (c1 - c0 + 1)
            objects.append((color, cells, r0, r1, c0, c1, hollow))

    out = [[0] * w for _ in range(h)]
    for upward in (True, False):
        group = [obj for obj in objects if obj[6] == upward]
        group.sort(key=lambda obj: obj[2] if upward else -obj[3])
        placed = []
        for color, cells, r0, r1, c0, c1, _ in group:
            step, shift = (-1 if upward else 1), 0
            while True:
                nxt = shift + step
                nr0, nr1 = r0 + nxt, r1 + nxt
                if nr0 < 0 or nr1 >= h:
                    break
                collision = any(not (c1 < p[4] or c0 > p[5]) and not (nr1 < p[2] or nr0 > p[3])
                               for p in placed)
                if collision:
                    break
                shift = nxt
            placed.append((color, cells, r0 + shift, r1 + shift, c0, c1, upward))
            for y, x in cells:
                out[y + shift][x] = color
    return out

